import sys, jax, jax.numpy as jnp
sys.path.insert(0, '"'"'/workspace'"'"'); import losses
V=12; z = jax.random.normal(jax.random.key(1),(V,))*2; zq = z + jax.random.normal(jax.random.key(2),(V,))
lq = jax.nn.log_softmax(zq)
for corr in [None, losses.ISCorrection(high=2.0, outside="clamp"), losses.ISCorrection(low=0.5, high=5.0), losses.ISCorrection(low=0.8, high=1.2, sign="ppo"), losses.ISCorrection(stat="tv", high=0.2, sign="ppo")]:
  for K in [V, 4, 0]:
    for A in [1.0, -1.0]:
      tot = 0
      for y in range(V):
        tokens = jnp.array([[0, y]]); 
        b = dict(tokens=tokens, mask=jnp.array([[False, True]]), advantages=jnp.array([A]),
                 sampling_token_logprobs=jnp.array([[lq[y], 0.]]))
        if K:
          tl, ti = jax.lax.top_k(lq, K); b |= dict(sampler_topk_ids=jnp.stack([ti, ti])[None], sampler_topk_logprobs=jnp.stack([tl, tl])[None])
        g = jax.grad(lambda zz: losses.loss_fn_rl(jnp.stack([zz, zz])[None], lambda x: x, b, corr)[0])(z)
        tot = tot + jnp.exp(lq[y]) * g
      print(corr and (corr.high, corr.sign, corr.stat), K, A, float(jnp.abs(tot).max()))
